-- Everyday foods (meat, fish, eggs, dairy, grains, fruit, vegetables, nuts...) from the
-- USDA FoodData Central SR Legacy dataset (public domain, fdc.nal.usda.gov), per 100 g with
-- a common serving. Packaged products keep coming from Open Food Facts.

alter table public.foods drop constraint foods_source_check;
alter table public.foods add constraint foods_source_check check (source in ('seed', 'off', 'custom', 'usda'));















